/* @autogenerated */
import { Component, inject, Injector, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { Subject } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { BaseCreateAction } from './base-create-action';

interface Item {
  uid?: string;
  name: string;
}

const acl = signal<{ generic: Acl } | undefined>(undefined);
const repository = {
  // Como RepositoryService.acl(): necesita contexto de inyección
  acl: () => {
    inject(Injector);
    return Object.assign(acl, { fetch: jasmine.createSpy('fetch') }) as any;
  },
  add: jasmine.createSpy('add'),
};

@Component({ selector: 'test-create-action', template: '' })
class TestCreateAction extends BaseCreateAction<Item> {
  protected readonly scope = 'test';
  protected readonly repository = repository;
}

describe('BaseCreateAction', () => {
  let action: TestCreateAction;
  let container: jasmine.SpyObj<any>;

  beforeEach(() => {
    acl.set(undefined);
    repository.add.calls.reset();
    TestBed.configureTestingModule({
      imports: [TestCreateAction, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
    const fixture = TestBed.createComponent(TestCreateAction);
    fixture.detectChanges();
    action = fixture.componentInstance;
    container = jasmine.createSpyObj('ActionContainerComponent', ['close']);
    action.container.set(container);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('is a non contextual action named create', () => {
    expect(action.name).toBe('create');
    expect(action.contextual).toBeFalse();
  });

  it('is visible only with the create permission', () => {
    expect(action.visible([])()).toBeFalse();

    acl.set({ generic: { allows: [{ name: 'create', allowed: true }] } });
    expect(action.visible([])()).toBeTrue();
  });

  it('starts from an empty form', () => {
    action.form.setValue({ name: 'previous' });

    action.run();

    expect(action.form.value).toEqual({} as Item);
  });

  it('adds the value, tracks saving and closes the container', () => {
    const response = new Subject<Item>();
    repository.add.and.returnValue(response);
    action.run();
    action.form.setValue({ name: 'new' });

    action.save();

    expect(repository.add).toHaveBeenCalledWith({ name: 'new' });
    expect(action.saving()).toBeTrue();
    response.next({ uid: '1', name: 'new' });
    response.complete();
    expect(action.saving()).toBeFalse();
    expect(container.close).toHaveBeenCalled();
  });
});
